"""Assemble reports/phase1_report.md from results/phase1/*. Regenerable; missing parts marked pending."""
import json, glob, sys, numpy as np, pandas as pd
from pathlib import Path
from collective_id.paths import RESULTS, REPORTS, RUNS
out = RESULTS / "phase1"; L = []
SUF = sys.argv[1] if len(sys.argv) > 1 else "_eb"; TAG = "ridge" + SUF
EXPS = [f"phase1_a_z4{SUF}", f"phase1_a_z2{SUF}", f"phase1_a_z8{SUF}", f"phase1_a_z4_gru{SUF}", f"phase1_a_z4{SUF}_tuned"]
def P(x=""): L.append(x)
def md(df, ff=".3f"): return df.to_markdown(index=False, floatfmt=ff)
def ex(p): return Path(p).exists()
def J(p): return json.load(open(p)) if ex(p) else None
P("# Phase 1 report — Plan A: search-phase → tracking-phase individuality transfer (gate)\n")
P("Generated by `scripts/19_phase1_report.py` (2026-09-24). Pre-registered criteria: AGENT_SPEC §4.3.\n")
P("## 1. Execution environment\n")
tm = []
for e in sorted(glob.glob(str(RUNS / "phase1_*"))):
    ms = [json.load(open(f)) for f in glob.glob(e + "/seed*/fold*/metrics.json")]
    if ms: tm.append(dict(exp=Path(e).name, runs=len(ms), gpu_min_total=sum(m["train_min"] for m in ms), epochs_mean=np.mean([m["epochs"] for m in ms])))
if tm: P(md(pd.DataFrame(tm), ".1f")); P()
P("RTX 5080, torch 2.11+cu128; encoder/decoder training per fold takes seconds to a few minutes. brms teacher fits: see phase0_report.md.\n")
P("## 2. Data\n")
P("- Source: search-phase 1 s sequences (features: |Δθ|, signed Δθ, θ_pos, θ_mov, binary social quality, #visible, normalised distance; Alone participants have zeros in social features). Target: the paper's tracking-model participant random effects (intercept, Detector, θ_pos, θ_mov, θ_pos×quality, θ_mov×quality) from `runs/eb/tracking_all_ranef.csv` (EB fit; brms full fit abandoned for time — see phase0_report §4.4 and questions.md).")
P("- Split: `data/processed/split_v1.json` (10 folds, stratified by condition × speed, whole groups in one fold). Standardisation of inputs and of targets uses training participants of the fold only.")
P("- **Excluded from Phase 1: 53 participants with < 10 s of searching** (all slow resource: FP 27, A 10, NP 8, VP 8; they never lost the resource), leaving n = 568. They have no source sequence; see questions.md.")
P(f"- Teacher used for this report: {'EB (GPU empirical-Bayes fit of the paper model)' if SUF == '_eb' else 'brms (paper code)'}.")
rel = RESULTS / "phase0" / "split_half_reliability.csv"
if rel.exists() and rel.stat().st_size > 1:
    r = pd.read_csv(rel); r = r[(r.estimator == "eb") & (r.model == "tracking")]
    P("- **Noise ceiling** (split-half retest r of the teacher random effects, first vs second 7.5 min, EB fits): " + ", ".join(f"{c.replace('withSocInfo1:', '')} {v:.2f}" for c, v in zip(r.coef, r.r_first_second)) + ". Only the intercept and detector weights are reliably measured within a 15-min session; the social weights (especially the quality interactions = payoff selectivity) have ceilings of r ≈ 0.1–0.3, so no transfer model can predict them well from this data.\n")
P("## 3. Deviations from defaults\n")
P("- Target includes the participant intercept (paper RE structure) and excludes a distance weight (no such random slope in the paper's model) — see questions.md.")
P("- Early stopping uses a 10 % stratified validation subset of the training participants (spec: 'fold 内 early stop').")
P("- Baseline 'search-phase score' (§4.2-4) implemented as search-time-only ridge (search phase has zero score by definition).\n")
P("## 4. Results\n")
P("### 4.1 Upper-bound feel: linear ridge from search-phase summary statistics (§4.2-1)\n")
if ex(out / f"baselines_{TAG}.csv"):
    b = pd.read_csv(out / f"baselines_{TAG}.csv"); P(md(b.pivot(index="coef", columns="model", values="r").reset_index())); P()
    P("r between predicted and teacher random effects across held-out participants (all folds pooled). **Note on the constant baselines:** the teacher random effects are deviations from condition × speed fixed effects, so their cell means are ≈ 0 and the grand-mean / cell-mean predictions carry no signal; the negative r values are the leave-fold-out artefact of predicting a constant (held-out fold mean anti-correlates with the training mean). The meaningful reference for Δr is therefore r = 0, and the spec's Δr ≥ 0.10 criterion vs. the cell mean is trivially inflated — the pass/fail below reports Δr against both the cell mean (as pre-registered) and against 0. `pls_z4` is a **linear 4-d z** (PLS scores from the same summary statistics + condition one-hot) — the linear alternative allowed by §4.3.\n")
for exp in EXPS:
    if not ex(out / f"summary_{exp}.csv"): P(f"### {exp}: pending\n"); continue
    if exp.endswith("_tuned"): P("Additional (not pre-registered) variant: random-crop augmentation (240 s), AdamW weight decay 0.05, input-channel dropout 0.2, dropout 0.3, patience 60; seed 0 only.\n")
    P(f"### 4.2 Main experiment — {exp} (decoder a: z + condition → teacher weights)\n")
    P(md(pd.read_csv(out / f"summary_{exp}.csv"))); P()
    P("Paired comparisons (held-out participants; Δr with participant bootstrap 95 % CI; mixed model on per-participant standardised squared-error difference, baseline − model, participant random intercept over seeds):\n")
    P(md(pd.read_csv(out / f"paired_vs_baselines_{exp}.csv"), ".4f")); P()
    v = J(out / f"verdict_{exp}.json"); h2 = J(out / f"cross_individual_{exp}.json"); nu = J(out / f"nuisance_{exp}.json")
    if v:
        sm = pd.read_csv(out / f"summary_{exp}.csv"); P(f"**Verdict {exp}:** mean r (vs teacher) = {sm.r_mean.mean():.3f} (= Δr vs a constant prediction); mean Δr vs cell mean (pre-registered form) = {v['mean_delta_r_vs_cond_mean']:.3f}; mean Δr vs ridge = {v['mean_delta_r_vs_ridge']:.3f}; coefficients with mixed-model p<0.01 vs cell mean: {v['n_coefs_p_lt_0_01_vs_cond']}/6 → **A-H1 {'PASS' if v['A_H1_pass'] else 'FAIL'}** (fails because the encoder does not beat the linear ridge baseline).\n")
    if h2: P(f"A-H2 (cross-individual): log squared error of predicting k from l's z ~ ‖z_k−z_l‖ (standardised): slope {h2['z_dist']['params']['dz_s']:.3f}, p = {h2['z_dist']['pvalues']['dz_s']:.2e}; summary-statistic distance slope {h2['summary_dist']['params']['ds_s']:.3f}, p = {h2['summary_dist']['pvalues']['ds_s']:.2e}; joint model: z {h2['both']['params']['dz_s']:.3f} vs summary {h2['both']['params']['ds_s']:.3f} → **A-H2 {'PASS' if h2['A_H2_pass'] else 'FAIL'}** (positive error slope = negative performance slope).\n")
    if nu: P(f"Nuisance (§4.5): condition decodable from z with CV accuracy {nu['cond_decoding_acc']:.3f} (chance {nu['cond_chance']:.3f}; flag >0.5: {nu['flag_condition_encoded']}); speed {nu['speed_decoding_acc']:.3f} (chance {nu['speed_chance']:.3f}). Spearman ρ of z dims with duplicates %, time-in-experiment, score, first-minute rotation frequency/magnitude/no-move fraction:\n"); P(pd.DataFrame(nu["spearman_z_vs_nuisance"]).round(2).to_markdown()); P()
    P(f"Figures: `fig_transfer_{exp}.png`, `fig_zspace_{exp}.png`, `fig_distance_{exp}.png`.\n")
if ex(out / f"nll_b_summary_phase1_b_z4{SUF}.csv"):
    P("### 4.3 Decoder (b): z-conditioned rotation predictor (held-out tracking NLL per second)\n"); P(pd.read_csv(out / f"nll_b_summary_phase1_b_z4{SUF}.csv").round(4).to_markdown(index=False)); t = J(out / f"nll_b_test_phase1_b_z4{SUF}.json"); P(f"\nMixed-model NLL gain vs condition×speed population weights: {t['gain_vs_pop']:.4f} nats/s (p = {t['p']:.2e}); median fraction of the oracle (own in-sample fit) gain captured: {t['median_frac_of_oracle_gain']:.3f}.\n")
else: P("### 4.3 Decoder (b): pending\n")
if ex(out / f"sim_recovery_summary_phase1_a_z4{SUF}.csv"):
    P("### 4.4 Simulated individuals (§4.2-6)\n"); P(md(pd.read_csv(out / f"sim_recovery_summary_phase1_a_z4{SUF}.csv"))); P("\n500 ABM agents (paper ABM, heterogeneous β1, k, r_max, x0; 100 groups of 5) encoded by each fold/seed encoder; 5-fold ridge R² of parameters from z. Note: the paper's ABM has no separate position/movement weights; searching agents differ in r_max, k, x0 (β1 only acts during tracking, so low R² for β1 is expected from search-phase input).\n")
else: P("### 4.4 Simulated individuals: pending\n")
if ex(out / f"icc_phase1_a_z4{SUF}.csv"):
    P("### 4.5 Temporal stability of z (§4.2-7)\n"); i = pd.read_csv(out / f"icc_phase1_a_z4{SUF}.csv"); P(i.groupby("dim").agg(icc21_mean=("icc21", "mean"), icc21_sd=("icc21", "std"), r_mean=("r", "mean"), n=("n", "first")).round(3).to_markdown()); P()
else: P("### 4.5 Temporal stability: pending\n")
if ex(out / "lr_sweep_summary.csv"):
    P("### 4.6 Learning-rate sensitivity (requested 2026-09-24; decoder a, z=4, **no early stopping**, 500 epochs, seed 0, 10 folds)\n")
    P(pd.read_csv(out / "lr_sweep_summary.csv", index_col=0).round(3).to_markdown()); P()
    P("Held-out r of the final-epoch model. Validation loss rises from epoch ≈ 10–20 at lr ≥ 1e-4 (over-fitting) and never drops below its epoch-0 value by more than ≈ 0.02 at any learning rate; at lr ≤ 1e-5 the model barely moves in 500 epochs. Mean r peaks at lr = 1e-4 (0.145) but stays below the linear ridge baseline (0.174); the intercept is best learned at 1e-3, the detector weight at 1e-4. Conclusion: the learning rate is not the bottleneck — no setting between 1e-6 and 1e-3 lets the sequence encoder beat the linear baseline. Figure: `fig_lr_sweep.png`.\n")
if ex(out / "lr_sweep_10k_summary.csv"):
    P("### 4.7 Learning-rate sensitivity with 10,000 epochs (requested 2026-09-24; same design, no early stopping, ≈ 15 GPU-min per fold)\n")
    P(pd.read_csv(out / "lr_sweep_10k_summary.csv", index_col=0).round(3).to_markdown()); P()
    P("With 10,000 epochs every learning rate ≥ 1e-5 reaches near-zero training loss, and the validation loss ends **above** its starting value for every learning rate (1e-6: 1.20 vs 1.16 at its epoch-3000 minimum; 1e-5: 1.38; ≥ 3e-5: 1.39–1.45). The held-out mean r is 0.06–0.15 (best 3e-4: 0.151; 1e-3: 0.144), again below the linear ridge baseline (0.174); the intercept reaches 0.42 at 1e-3 vs 0.56 for ridge, the detector weight 0.21 vs 0.34. Long training with a small learning rate merely reproduces, more slowly, the same over-fitting trajectory. Figure: `fig_lr_sweep_10k.png`.\n")
if ex(out / "lr_sweep_50k_summary.csv"):
    P("### 4.8 Learning-rate sensitivity with 50,000 epochs (requested 2026-09-25; same design, no early stopping, ≈ 75 GPU-min per fold, 6 runs in parallel ≈ 15 h)\n")
    P(pd.read_csv(out / "lr_sweep_50k_summary.csv", index_col=0).round(3).to_markdown()); P()
    P("At 50,000 epochs all learning rates converge to the same regime: training loss ≈ 0 (1e-6: 0.50 and still falling), validation loss 1.40–1.55 for lr ≥ 1e-5 and 1.31 and rising for 1e-6 (its minimum, 1.16, was at epoch ≈ 3,000). Held-out mean r is 0.09–0.14 (best 3e-4: 0.136), below the 10k-epoch values (0.15) and below the linear ridge baseline (0.174). The detector weight reaches its best value so far at 3e-4 (0.19) but the intercept degrades (0.35–0.38 vs 0.42 at 10k epochs) and the quality interactions stay at ≈ 0. Longer training only moves the encoder further into the over-fitting regime; the ranking encoder < linear baseline is unchanged across 500 / 10,000 / 50,000 epochs and six learning rates. Figure: `fig_lr_sweep_50k.png`.\n")
P("## 5. Pass/fail (pre-registered §4.3)\n")
v = J(out / f"verdict_phase1_a_z4{SUF}.json")
if v: P(f"- A-H1: **{'PASS' if v['A_H1_pass'] else 'FAIL'}** (criterion: mean Δr ≥ 0.10 vs condition×speed mean, mixed-model p < 0.01, and beats ridge). Observed: Δr_cond = {v['mean_delta_r_vs_cond_mean']:.3f}, Δr_ridge = {v['mean_delta_r_vs_ridge']:.3f}.")
if v: P(f"- A-H2: **{'PASS' if v['A_H2_pass'] else 'FAIL'}** (negative performance–distance slope, p < 0.001, z distance beats summary-statistic distance).")
P("- Per §4.3: the non-linear encoder lost to the linear ridge baseline on every reliably-measured coefficient → **'非線形の z は不要'**; the linear z (`results/phase1/z_linear_pls4_" + TAG + ".csv`, PLS scores of search-phase summary statistics) is the recommended substitute for a search-phase z. Since 53 participants have no search phase and social weights have a low noise ceiling, Phase 3 should default to a **tracking-phase-derived z** (spec default), with the linear search-phase z as a secondary analysis.\n")
P("## 6. Anomalies / failures\n")
P("- The full brms tracking fit (paper code) was stopped after 4 h 45 min at warm-up iteration 200/2500 (projected > 1 day per model); teacher = GPU empirical-Bayes fit of the identical model (diagonal RE covariance). A 20 % subsample brms fit is running to quantify EB–brms agreement (§7).")
P("- Pipeline script bug (extra `--tag` flag) aborted the simulated-agent and ICC steps once; both were re-run manually with identical arguments (results above).")
P("- The `_tuned` variant was run with one seed, so its mixed-model p-values are degenerate (NaN) — its Δr and bootstrap CIs are valid.")
P("- The CNN encoder overfits within ~10 epochs (training loss → 0.3 while validation never improves beyond epoch ≈ 5); stronger regularisation did not help. With 450 training participants and low-reliability targets, a sequence encoder has no advantage over hand-crafted summary statistics.")
P("- A-H2 caveat: because the decoder is a smooth function of z, prediction error necessarily grows with ‖z_k − z_l‖; the informative part of the test is that z distance explains error better than the raw summary-statistic distance (it does, in the joint model), not the slope itself.\n")
P("## 7. Unverified / validation of the teacher\n")
cmpf = RESULTS / "phase0" / "teacher_eb_vs_brms.csv"
if cmpf.exists() and cmpf.stat().st_size > 1:
    c = pd.read_csv(cmpf); P("- EB vs brms (paper code, 20 % participant subsample, 4 × 1500 iterations, R̂ ≤ 1.015, 0 divergences, 98 min) — per-participant random effects on the same 121 participants:\n"); P(md(c)); P("\n  Agreement r = 0.90–0.998 (intercept/detector ≈ 0.99; social weights ≈ 0.9). The EB teacher is therefore a close proxy for the brms posterior means on the full sample; EB shrinks social random effects slightly more (smaller SD).")
else: P("- EB vs brms agreement: pending.")
P("- Fixed effects of the EB fit reproduce the paper's Fig 4 orderings (see phase0_report §4.5b).")
P("- Results are on 568 participants (search-phase available); generalisation to the 53 never-searching participants is untested.\n")
P("## 8. Questions for the human (→ reports/questions.md)\n")
P("1. **z source for Phase 3** (spec §4.6): recommendation = tracking-phase-derived z (default), because (a) A-H1 failed, (b) 53 participants have no search phase, (c) social-weight ceilings are low. Secondary: linear search-phase z (`z_linear_pls4_ridge_eb.csv`).")
P("2. **Linear vs non-linear z**: the encoder lost to ridge/PLS; per §4.3 the linear z may substitute. Should Phase 3's D-1 hypernetwork also be linear (z → ABM parameters by ridge)?")
P("3. **Teacher**: accept the EB estimator (same model, 10 min) as the teacher, or run the paper's brms fits over several days?")
P("4. **4-person groups** (38 of 103): simulate 4 agents, 5 with the excluded member, or drop?")
P("5. **Pre-registration wording**: the Δr-vs-cell-mean criterion is uninformative for random effects (cell means ≈ 0); propose replacing it with Δr vs 0 and vs the linear baseline for Phases 2–3 (see questions.md; the original criterion was still applied here).\n")
(REPORTS / "phase1_report.md").write_text("\n".join(L)); print("report written")
